import RAPIER from '@dimforge/rapier3d-compat';
import { GAME_CONFIG } from '../config/GameConfig';
import type { Vec3 } from '../contracts/math';

export class PhysicsWorld {
  readonly world: RAPIER.World;
  private accumulator = 0;
  readonly fixedStep: number;

  constructor(gravity: Vec3 = GAME_CONFIG.physics.gravity, fixedStep = 1 / GAME_CONFIG.targetFps) {
    this.world = new RAPIER.World(gravity);
    this.fixedStep = fixedStep;
    this.world.timestep = fixedStep;
  }

  step(deltaSeconds: number, beforeStep?: (dt: number) => void): void {
    this.accumulator += Math.min(Math.max(deltaSeconds, 0), 0.25);
    while (this.accumulator >= this.fixedStep) {
      beforeStep?.(this.fixedStep);
      this.world.step();
      this.accumulator -= this.fixedStep;
    }
  }

  dispose(): void {
    this.world.free();
  }
}
