import type { Quat, Vec3 } from '../contracts/math';
import type { ObstacleDescriptor } from '../courses/types';

/** World-space placement shared by an obstacle visual and its physics body. */
export interface ObstaclePose {
  position: Vec3;
  rotation: Quat;
}

/** Renderable half of an obstacle, owned by the factory that created it. */
export interface ObstacleVisual {
  setPose(pose: ObstaclePose): void;
  setEnabled(enabled: boolean): void;
  dispose(): void;
}

/** Physics half of an obstacle, owned by the factory that created it. */
export interface ObstacleBody {
  setPose(pose: ObstaclePose): void;
  setEnabled(enabled: boolean): void;
  dispose(): void;
}

export interface ObstacleVisualFactory {
  create(descriptor: ObstacleDescriptor): ObstacleVisual;
}

export interface ObstacleBodyFactory {
  create(descriptor: ObstacleDescriptor): ObstacleBody;
}

/** Read-only view of one live obstacle held by the ObstacleManager. */
export interface ObstacleInstance {
  readonly id: string;
  readonly descriptor: ObstacleDescriptor;
  readonly basePose: ObstaclePose;
  readonly pose: ObstaclePose;
  readonly enabled: boolean;
  readonly elapsedSeconds: number;
  readonly moving: boolean;
  readonly visual: ObstacleVisual | null;
  readonly body: ObstacleBody | null;
}
